previewCss:
.darma-loader-darma-b11-piano-keys { --accent: var(--loader-color, #8b5cf6); --accent-2: var(--loader-secondary-color, #ec4899); width: var(--loader-size, 96px); height: calc(var(--loader-size, 96px) * .5); display: flex; gap: calc(var(--loader-size, 96px) * .015); perspective: 300px; }
.darma-loader-darma-b11-piano-keys span { flex: 1; background: #f8fafc; border-radius: 0 0 5px 5px; transform-origin: top center; box-shadow: inset 0 -4px 6px rgba(0, 0, 0, .12); animation: darma-loader-darma-b11-piano-keys-press calc(var(--loader-speed, 1s) * 1.2) ease-in-out infinite; }
.darma-loader-darma-b11-piano-keys span:nth-child(1) { animation-delay: 0s; }
.darma-loader-darma-b11-piano-keys span:nth-child(2) { animation-delay: calc(var(--loader-speed, 1s) * .12); }
.darma-loader-darma-b11-piano-keys span:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * .24); }
.darma-loader-darma-b11-piano-keys span:nth-child(4) { animation-delay: calc(var(--loader-speed, 1s) * .36); }
.darma-loader-darma-b11-piano-keys span:nth-child(5) { animation-delay: calc(var(--loader-speed, 1s) * .48); }
@keyframes darma-loader-darma-b11-piano-keys-press { 0%, 100% { transform: rotateX(0deg); background: #f8fafc; } 50% { transform: rotateX(30deg); background: linear-gradient(var(--accent), var(--accent-2)); } }

